module apb_watchdog(pclk, presetn, psel, penable, pwrite, paddr, pwdata, pstrb, 
    prdata, pready, pslverr, rtc_tick, wdt_irq, wdt_rst);
input  pclk, presetn, psel, penable, pwrite, rtc_tick;
output pready, pslverr, wdt_irq, wdt_rst;
input   [11:0] paddr;
input   [31:0] pwdata;
